<?php

namespace Database\Seeders;

use App\Enums\CourseStatus;
use App\Enums\ExamQuestionOrderMode;
use App\Enums\ExamStatus;
use App\Enums\QuestionDifficulty;
use App\Enums\QuestionType;
use App\Models\Course;
use App\Models\Exam;
use App\Models\ExamQuestion;
use App\Models\Question;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use RuntimeException;

class IadcExamQuestions2026Seeder extends Seeder
{
    private const EMBEDDED_DATA = '';

    /** @var array<int, array{legacy_id: int, code: string, name: string, file: string}> */
    private const LEGACY_SUBJECTS = [
        ['legacy_id' => 1, 'code' => 'drilling-operation-driller-surface', 'name' => 'Drilling Operation, Driller, Surface', 'file' => 'drilling_operation_driller_surface_questions.csv'],
        ['legacy_id' => 2, 'code' => 'drilling-operation-supervisor-surface', 'name' => 'Drilling Operation, Supervisor,Surface', 'file' => '2_Drilling_Operation,_Supervisor,Surface_questions.csv'],
        ['legacy_id' => 3, 'code' => 'well-servicing-coiled-tubing', 'name' => 'Well Servicing Coiled Tubing', 'file' => '3_Well_Servicing_Coiled_Tubing_questions.csv'],
        ['legacy_id' => 4, 'code' => 'drilling-operation-introductory', 'name' => 'Drilling Operation, Introductory', 'file' => '4_Drilling_Operation,_Introductory_questions.csv'],
        ['legacy_id' => 5, 'code' => 'well-servicing-wireline', 'name' => 'Well Servicing WireLine', 'file' => '5_Well_Servicing_WireLine_questions.csv'],
        ['legacy_id' => 6, 'code' => 'well-servicing-workover', 'name' => 'Well Servicing Workover', 'file' => '6_Well_Servicing_Workover_questions.csv'],
        ['legacy_id' => 7, 'code' => 'well-servicing-ogor', 'name' => 'Well Servicing Oil and Gas Operator Representative', 'file' => '7_Well_Servicing_Oil_and_Gas_Operator_Representative_questions.csv'],
        ['legacy_id' => 99, 'code' => 'driller-kill-sheet', 'name' => 'Driller kill sheet', 'file' => '99_Driller_kill_sheet_questions.csv'],
        ['legacy_id' => 100, 'code' => 'supervisor-kill-sheet', 'name' => 'Supervisor kill sheet', 'file' => '100_Supervisor_kill_sheet_questions.csv'],
        ['legacy_id' => 101, 'code' => 'instructor-drilling-operations-supervisor-surface', 'name' => 'Instructor: Drilling Operations, Supervisor, Surface', 'file' => '101_Instructor__Drilling_Operations,_Supervisor,_Surface_questions.csv'],
        ['legacy_id' => 102, 'code' => 'instructor-well-servicing-workover', 'name' => 'Instructor Well Servicing Workover', 'file' => '102_Instructor_Well_Servicing_Workover_questions.csv'],
    ];

    public function run(): void
    {
        $dataset = self::dataset();
        $questionNumber = 0;

        DB::transaction(function () use ($dataset, &$questionNumber): void {
            foreach ($dataset['subjects'] as $subject) {
                $course = Course::query()->firstOrCreate(
                    ['code' => $subject['code']],
                    ['name' => $subject['name'], 'description' => 'Questions imported from '.$subject['file'].'.', 'status' => CourseStatus::Active],
                );
                $exam = Exam::query()->firstOrCreate(
                    ['code' => 'IADC26-'.str_pad((string) $subject['legacy_id'], 3, '0', STR_PAD_LEFT)],
                    ['course_id' => $course->id, 'name' => 'IADC 2026 '.$subject['name'], 'description' => 'Question bank source: '.$subject['file'].'.', 'passing_score' => 75, 'retake_score' => 60, 'certificate_validity_years' => 2, 'question_order_mode' => ExamQuestionOrderMode::Static, 'status' => ExamStatus::Draft],
                );

                $seenHashes = [];
                $displayOrder = 0;
                foreach ($subject['questions'] as $questionData) {
                    $hash = Question::textHash($questionData['question']);
                    if (isset($seenHashes[$hash])) continue;
                    $seenHashes[$hash] = true;
                    $displayOrder++;
                    $questionNumber++;
                    $question = Question::query()->updateOrCreate(
                        ['code' => 'I'.str_pad((string) $questionNumber, 4, '0', STR_PAD_LEFT)],
                        ['course_id' => $course->id, 'question_text' => $questionData['question'], 'type' => QuestionType::Mcq, 'difficulty' => QuestionDifficulty::Medium, 'default_marks' => $questionData['degree'] ?: 1, 'correct_answer_text' => $questionData['text_answer'], 'correct_answer_boolean' => null, 'solution_text' => null, 'is_active' => true],
                    );
                    ExamQuestion::query()->updateOrCreate(
                        ['exam_id' => $exam->id, 'question_id' => $question->id],
                        ['display_order' => $displayOrder, 'points' => $questionData['degree'] ?: 1],
                    );
                }
            }
        });
    }

    /** @return array<int, array{legacy_id: int, code: string, name: string}> */
    public static function legacySubjects(): array
    {
        return array_map(static fn (array $subject): array => ['legacy_id' => $subject['legacy_id'], 'code' => $subject['code'], 'name' => $subject['name']], self::LEGACY_SUBJECTS);
    }

    /** @return array{version: string, subjects: array<int, array<string, mixed>>} */
    public static function dataset(): array
    {
        $json = gzdecode(base64_decode(self::EMBEDDED_DATA, true));
        if ($json === false) throw new RuntimeException('Unable to decode embedded subject question data.');
        $dataset = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
        if (! is_array($dataset) || ! isset($dataset['subjects']) || ! is_array($dataset['subjects'])) {
            throw new RuntimeException('Embedded subject question data is invalid.');
        }
        return $dataset;
    }
}
